export function getLibraryEntry(category) {
  return SCAM_LIBRARY.find((entry) => entry.category === category) || null;
}

// --------------------------------------------------- "Looks like a known scam"
// Simple word-overlap (cosine similarity of word counts) against the example
// messages above. Runs in the browser. It is wording overlap, not a probability.
const STOP = new Set('the a an and or of to in on for is are be you your we our this that it at by with from have has will can please dear'.split(' '));

function vector(text) {
  const v = new Map();
  for (const w of String(text).toLowerCase().normalize('NFKC').match(/[\p{L}\p{N}]+/gu) || []) {
    if (w.length < 2 || STOP.has(w)) continue;
    v.set(w, (v.get(w) || 0) + 1);
  }
  return v;
}

function cosine(a, b) {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (const [, x] of a) na += x * x;
  for (const [, x] of b) nb += x * x;
  for (const [k, x] of a) if (b.has(k)) dot += x * b.get(k);
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

const EXAMPLE_VECTORS = SCAM_LIBRARY.flatMap((entry) => entry.examples.map((text) => ({ entry, text, v: vector(text) })));

export const KNOWN_SCAM_THRESHOLD = 0.3;

export function matchKnownScam(text) {
  const v = vector(text);
  if (v.size < 3) return null;
  let best = null;
  for (const ex of EXAMPLE_VECTORS) {
    const score = cosine(v, ex.v);
    if (!best || score > best.score) best = { ...ex, score };
  }
  if (!best || best.score < KNOWN_SCAM_THRESHOLD) return null;
  return { category: best.entry.category, title: best.entry.title, example: best.text, overlap: Math.round(best.score * 100) };
}
